from lib import *
S = SS('s3')
steps = [
    step("CrawlerProcess 和 AsyncCrawlerProcess 的 start() 都只能调一次:第一次爬 10 个各延迟 0.3 s 的页面,start() 分别在 0.62 s 和 0.78 s 后返回(此时 reactor 已停);紧接着再 crawl 一次、再 start,两个类都抛 twisted.internet.error.ReactorNotRestartable。Twisted 的 reactor 停下之后不能重启,所以同一个进程里要爬第二次,只能事先把所有 crawl 都排好再 start 一次,或者改用 Runner 自己管 reactor。", t=tl(S(1)), mark=lidx(S(1), 'ReactorNotRestartable'), done=lidx(S(1), '第一次 start()'), kv=KV([['第一次 start()', '返回,reactor 已停'], ['第二次 start()', 'ReactorNotRestartable'], ['两个类都一样', 'CrawlerProcess / AsyncCrawlerProcess']], ['第二次 start()'])),
    step("同一个进程里跑两个 spider(各 10 个页面,并发 10,延迟 0.3 s):CrawlerProcess 先 crawl(A)、crawl(B) 再 start(),两个 spider 同时跑,总耗时 0.62 s;CrawlerRunner 里用 inlineCallbacks 依次 yield crawl(A)、crawl(B),顺序执行,总耗时 1.39 s。两种方式服务器都收到 20 个请求。CrawlerProcess 并发的前提是 start 之前把所有 crawl 登记完。", t=tl(S(2)), mark=lidx(S(2), 'CrawlerProcess:crawl', 'CrawlerRunner:yield'), done=lidx(S(2), '两种方式'), b=bars([['CrawlerProcess 并发', 0.62, '0.62 s'], ['CrawlerRunner 顺序', 1.39, '1.39 s']], 1.39, mark=[0], done=[1]), kv=KV([['CrawlerProcess', 'crawl(A); crawl(B); start() → 0.62 s'], ['CrawlerRunner 链式', 'yield A; yield B → 1.39 s'], ['请求数', '都是 20']], ['CrawlerProcess'])),
    step("CrawlerRunner 把 reactor 交给你管:(a) 没先 install_reactor 就 crawl,Deferred 里抛 RuntimeError: We expected a Twisted reactor to be installed but it isn't.(进程退出码仍是 0,只是日志里报 Unhandled error in Deferred);(b) 装了 reactor、crawl 完成后没有调用 reactor.stop():“crawl 的 Deferred 触发了”已经打印,但 reactor.run() 永远不返回,进程 5 秒后被我杀掉(退出码 -9);(c) d.addBoth(lambda _: reactor.stop()) 才正常退出,1.14 s。", t=tl(S(3)), mark=lidx(S(3), '(b)', 'RuntimeError'), done=lidx(S(3), '(a)', '(c)'), kv=KV([['(a) 没装 reactor', 'RuntimeError,退出码 0'], ['(b) 不 stop', 'Deferred 已触发但进程不退出'], ['(c) addBoth(reactor.stop)', '1.14 s 正常退出']], ['(b) 不 stop'])),
    step("在 asyncio 程序里用 AsyncCrawlerRunner:先 install_reactor(asyncio reactor) 再 asyncio.run(main()) 会卡死——8 秒超时被杀,第一个 crawl 都没完成(asyncio.run 新建的是另一个事件循环,不是 reactor 在用的那个)。两种能跑通的写法:TWISTED_REACTOR_ENABLED=False 加 asyncio.run,两次 crawl 都完成,1.7 s;或者保留 reactor,用 Deferred.fromFuture(asyncio.ensure_future(main())) 再 reactor.run(),也是 1.7 s。", t=tl(S(4)), mark=lidx(S(4), '装了 asyncio reactor + asyncio.run'), done=lidx(S(4), 'TWISTED_REACTOR_ENABLED=False', 'Deferred.fromFuture'), kv=KV([['reactor + asyncio.run', '卡死(8 秒超时)'], ['无 reactor + asyncio.run', '1.7 s,两次 crawl 完成'], ['reactor + fromFuture', '1.7 s,两次 crawl 完成']], ['reactor + asyncio.run'])),
    step("Ctrl-C:CrawlerProcess 自己装了信号处理。第 1.5 s 发一次 SIGINT:日志 “Received SIGINT, shutting down gracefully. Send again to force”,“Closing spider (shutdown)”,等已经发出的 4 个请求(服务器每个延迟 3 s)做完,进程在 3.5 s 退出,finish_reason=shutdown,后面没有再发新请求(服务器共收到 4 个请求)。间隔 0.5 s 连发两次:第二次打印 “Received SIGINT twice, forcing unclean shutdown”,2.5 s 就退出,stats 没有打出来(finish_reason 取不到)。", t=tl(S(5)), mark=lidx(S(5), 'Received SIGINT twice', '间隔 0.5 s'), done=lidx(S(5), '发一次 SIGINT', 'shutting down gracefully', 'finish_reason=shutdown'), b=bars([['一次 SIGINT', 3.5, '3.5 s'], ['两次 SIGINT', 2.5, '2.5 s']], 3.5, mark=[1], done=[0]), kv=KV([['一次 SIGINT', '优雅停止:等在途请求,finish_reason=shutdown'], ['两次 SIGINT', '强制退出,不写 stats'], ['新请求', '收到信号后不再发出']], ['一次 SIGINT'])),
]
A = mkarts('s3', 3, 'Scrapy,CrawlerProcess,CrawlerRunner,reactor,信号,真实验证,动画演示',
    '实测 Scrapy 2.19 的四个启动类:start() 只能调一次(第二次 ReactorNotRestartable);CrawlerProcess 并发两个 spider 0.62 s、CrawlerRunner 顺序 1.39 s;CrawlerRunner 不 stop reactor 进程永远不退出;asyncio.run 配 asyncio reactor 会卡死;第一次 SIGINT 优雅停止、第二次强制退出。',
    '在脚本里启动 Scrapy,有 CrawlerProcess、CrawlerRunner 和 2.19 里新出现的 Async 版本。谁装 reactor、谁停 reactor、能不能跑第二次、Ctrl-C 之后发生什么——这篇一项项实测。',
    [('ReactorNotRestartable', '同一个进程里第二次 start() 抛出的异常'), ('0.62 vs 1.39 s', '两个 spider:CrawlerProcess 并发与 CrawlerRunner 顺序的总耗时'), ('2 次 SIGINT', '第一次优雅停止(等在途请求),第二次强制退出')],
    [('start() 只能一次', '<p>reactor 停下后不能再启动,所以脚本里要么把所有 <code>crawl()</code> 排好再 <code>start()</code> 一次,要么自己管 reactor。</p>'),
     ('并发与顺序', '<p><code>CrawlerProcess</code> 把多个 crawler 交给同一个 reactor 并发跑;<code>CrawlerRunner</code> 只给你 Deferred,想顺序就自己链起来。</p>'),
     ('Runner 不管 reactor', '<p><code>CrawlerRunner</code> 要求 reactor 已经装好、爬完以后由你停掉;忘了 stop 进程不会退出。</p>'),
     ('asyncio 程序里', '<p>2.19 的 <code>AsyncCrawlerRunner</code> 返回可 await 的任务,但事件循环要和 reactor 是同一个,或者干脆用无 reactor 模式。</p>'),
     ('信号', '<p><code>CrawlerProcess</code> 装了 SIGINT/SIGTERM 处理:第一次让引擎优雅关闭,第二次强制退出。</p>')],
    steps,
    [ENV_Y + '。每个情形是独立进程里的一个小脚本(10 个页面,服务器端 time.sleep 制造延迟);第五节用 subprocess.Popen 启动脚本再 send_signal(SIGINT)',
     '没有验证:SIGTERM 的行为;在 Windows 上的信号处理;和别的 asyncio 库(aiohttp 服务器、FastAPI)放在同一个事件循环里的细节;CrawlerRunner 并发多个 crawler 时的 settings 隔离;AsyncCrawlerProcess 的 stop_after_crawl=False 用法;强制退出时 pipeline、feed 是否丢数据'],
    '启动与停止')
